SELECT COUNT(*)
FROM community_chief_cash_withdrawal
WHERE company_id = #{companyId}
  AND distributor_id = #{distributorId}

	AND mobile = #{mobileEnc}


	AND status = #{status}

SELECT id, company_id, distributor_id, chief_id, pay_account, account_name, bank_name, mobile, money, status,
       remarks, pay_type, wxa_appid, created, updated
FROM community_chief_cash_withdrawal
WHERE company_id = #{companyId}
  AND distributor_id = #{distributorId}

	AND mobile = #{mobileEnc}


	AND status = #{status}

ORDER BY created DESC
LIMIT #{offset}, #{limit}

SELECT chief_id AS chiefId, SUM(money) AS money FROM community_chief_cash_withdrawal WHERE status = 'apply' AND company_id = #{companyId} AND chief_id IN
#{cid}
GROUP BY chief_id

SELECT chief_id AS chiefId, SUM(money) AS money FROM community_chief_cash_withdrawal WHERE status = 'success' AND company_id = #{companyId} AND chief_id IN
#{cid}
GROUP BY chief_id
